    ["policy", "mistRemaining", "healRemaining", "mistHistory", "healHistory"].sort(),
  );
  expect(Object.keys(raven).sort()).toEqual(
    ["policy", "awakened", "knownTeammateIds", "extraRemaining", "extraHistory"].sort(),
  );
