import { createRoleCatalog } from "../../../src/game/mechanisms/roles/role-catalog-assembly";
import { renderRolePrompt } from "../../../src/game/observation/role-presentation";
import {
  WOLF_STAGE_DIRECTIVES,
  WOLF_TOOL_SPECS,
