import { bootstrapGame } from "../../../src/app/bootstrap";
import {
  Phase,
  Role,
  WinCondition,
  ActionWindow,
  WitchSelfHealRule,
  type ActionRequest,
  type BoardConfig,
  type ToolName,
  type ActionStage,
