    [2, "player 2"],
    [null, "is empty"],
    [undefined, "No definite"],
  ] as const) {
    const req = request(5, "witch", ["use_potion"], target);
    const before = getWitchState(english.world.getComponent(5, COMPONENT.Role)!);
