      const before = policy.buildBoardInfo();
      role(world, 6).role = Role.Wolf;
      role(world, 6).camp = Camp.Wolf;
      role(world, 3).role = Role.Villager;
      board.roleSetups[0].count = 99;
      board.boardSize = 99;
      expect(policy.buildBoardInfo()).toBe(before);
