      return null;
    },
  }, ActionWindow.OnPreVote, Phase.Voting)).resolves.toBeNull();
  expect(whiteRequests).toBe(1);
  expect(commitSelfDestructSelection(
    world, { kind: "white_wolf_king", actorId: 1, targetId: 3 },
